def _seed_tasks(client, token, n):
    ids = []
    for i in range(n):
        resp = client.post(
            "/api/tasks",
            json={"title": f"Task {i:02d}"},
            headers=_headers(token),
        )
        ids.append(resp.get_json()["task"]["id"])
    return ids


